<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {use} from 'echarts/core';
import {PieChart} from 'echarts/charts';
import {TooltipComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import VChart from 'vue-echarts';
import {managementRequest,cycleStage} from '../api/management';
use([PieChart,TooltipComponent,CanvasRenderer]);
const props=defineProps<{detail:any,results:any[],history:any[],scoreError?:string}>();
const emit=defineEmits<{(e:'department',d:{id:string|null,name:string}):void}>();
const rules=ref<any>(null),exceptions=ref<any[]|null>(null),ruleError=ref(''),exceptionError=ref('');let serial=0;
watch(()=>props.detail?.cycle?.id,async id=>{const seq=++serial;rules.value=null;exceptions.value=null;ruleError.value='';exceptionError.value='';if(!id)return;const ruleId=props.detail?.cycle?.ruleset_id;await Promise.all([ruleId?managementRequest(`rulesets/${encodeURIComponent(ruleId)}`).then(v=>{if(seq===serial)rules.value=v}).catch(()=>{if(seq===serial)ruleError.value='规则数据不可用'}):Promise.resolve(),managementRequest('management/exceptions').then(v=>{if(seq===serial)exceptions.value=v.filter((x:any)=>x.cycle_id===id&&!x.invalidated_at)}).catch(()=>{if(seq===serial)exceptionError.value='无权限查看异常记录或加载失败'})]);},{immediate:true});
const eligible=computed(()=>new Set((props.detail?.participants??[]).filter((p:any)=>p.eligibility==='ELIGIBLE').map((p:any)=>p.user_id)));
const published=computed(()=>props.results.filter(r=>eligible.value.has(r.target_id)));
const score=computed(()=>published.value.map(r=>r.payload_json?.final_score).filter(v=>v!=null&&Number.isFinite(Number(v))).map(Number));
const bands=[{label:'90–100 分',min:90,max:101,color:'#2868ed'},{label:'80–89 分',min:80,max:90,color:'#78a9f9'},{label:'60–79 分',min:60,max:80,color:'#bed7fc'},{label:'0–59 分',min:0,max:60,color:'#ffa154'}];
const distribution=computed(()=>bands.map(b=>({...b,count:score.value.filter(v=>v>=b.min&&v<b.max).length})));
const pie=computed(()=>({tooltip:{trigger:'item'},series:[{type:'pie',radius:['62%','82%'],label:{show:false},data:distribution.value.map(d=>({name:d.label,value:d.count,itemStyle:{color:d.color}}))}]}));
const dimensions=computed(()=>{const m=new Map<string,number[]>();for(const r of published.value)for(const item of r.payload_json?.peer_items??[]){if(!item.label||item.avg_score==null||!Number.isFinite(Number(item.avg_score)))continue;const list=m.get(item.label)??[];list.push(Number(item.avg_score));m.set(item.label,list)}return [...m].map(([label,v])=>({label,value:v.reduce((a,b)=>a+b,0)/v.length}))});
const departments=computed(()=>{const m=new Map<string,{id:string|null,name:string,count:number}>();for(const r of published.value){const id=r.department_id??null,key=id??'unassigned',d=m.get(key)??{id,name:r.department_name||'未分配',count:0};d.count++;m.set(key,d)}return [...m.values()].sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))});
const latest=computed(()=>props.history.map(r=>r.published_at).filter(Boolean).sort().at(-1));
const counts=computed(()=>{const all=exceptions.value??[];return [{label:'高分核验',count:all.filter(x=>['HIGH_TOTAL','EXCELLENT','HIGH_SCORE'].includes(x.reason_code)).length},{label:'低分核验',count:all.filter(x=>x.reason_code==='LOW_SCORE').length},{label:'评价理由不完整',count:all.filter(x=>x.reason_code==='MISSING_REASON').length},{label:'待处理异常',count:all.filter(x=>x.status==='OPEN').length},{label:'已处理',count:all.filter(x=>['RESOLVED','DISMISSED'].includes(x.status)).length}]});
function date(v:any){return v?new Date(v).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—'}
</script>
<template><div class="report"><header class="report-head"><h2>{{detail.cycle.title}} <small>{{cycleStage(detail.cycle.status)}}</small></h2><p>组织评价回顾与成长分析报告</p></header><div class="summary"><div><span>评价周期</span><b>{{detail.cycle.month}}</b></div><div><span>阶段</span><b>{{cycleStage(detail.cycle.status)}}</b></div><div><span>评价时间</span><b>{{date(detail.cycle.open_at)}} — {{date(detail.cycle.close_at)}}</b></div><div><span>最近发布时间</span><b>{{date(latest)}}</b></div><div><span>规则版本</span><b>{{detail.cycle.rule_version!=null?'v'+detail.cycle.rule_version:'—'}}</b></div><div><span>有效参评人数</span><b>{{eligible.size}}</b></div></div><div class="layout"><main><section id="archive-results" class="card"><h3><i>01</i> 评价结果概览</h3><p class="hint">本期正式发布的有效他评结果 · 当前授权范围</p><p v-if="scoreError" class="empty">成绩数据不可用：{{scoreError}}</p><p v-else-if="!score.length" class="empty">尚无正式发布结果</p><template v-else><p v-if="published.length<eligible.size" class="hint">已发布 {{published.length}} / {{eligible.size}} 人，以下统计仅覆盖已发布成员。</p><div class="charts"><div class="distribution"><div class="pie"><VChart :option="pie" autoresize class="chart"/><div class="pie-label">成绩分布<br><b>{{score.length}} 人</b></div></div><div class="legend"><div v-for="b in distribution" :key="b.label"><em :style="{background:b.color}"/>{{b.label}} <span>{{b.count}} 人（{{(b.count/score.length*100).toFixed(1)}}%）</span></div></div></div><div class="dimensions"><strong>各维度整体平均表现</strong><div v-for="d in dimensions" :key="d.label" class="dimension"><span>{{d.label}}</span><progress max="100" :value="d.value"/><b>{{d.value.toFixed(2)}}</b></div><p v-if="!dimensions.length" class="hint">暂无维度数据</p></div></div><p class="note">成绩来自最新正式发布快照，自评不计入；维度先取每位成员的有效他评均分，再计算授权范围内的平均值。</p></template></section><section id="archive-rules" class="card"><h3><i>02</i> 本期评分细则 <small>规则版本 {{detail.cycle.rule_version!=null?'v'+detail.cycle.rule_version:'—'}}</small></h3><p v-if="ruleError" class="empty">{{ruleError}}</p><template v-else-if="rules"><details v-for="t in rules.templates" :key="t.id" open><summary>{{t.name}} · {{t.role_code}}</summary><div class="scroll"><table><thead><tr><th>评价维度</th><th>权重</th><th>维度说明</th></tr></thead><tbody><tr v-for="item in t.items??[]" :key="item.code"><td>{{item.label}}</td><td>{{item.weight}}%</td><td>{{item.description||'—'}}</td></tr></tbody></table></div></details><p v-if="!rules.templates?.length" class="hint">暂无评价模板</p></template><p v-else class="empty">暂无规则数据</p></section></main><aside><section class="card guide"><h3>报告导览</h3><a v-for="[id,label] in [['archive-results','评价结果概览'],['archive-rules','本期评分细则'],['archive-departments','部门表现分析'],['archive-exceptions','异常与问题回顾'],['archive-ai','AI 成长总结']]" :key="id" :href="'#'+id">{{label}} →</a></section><section class="card"><h3>评价规则说明</h3><p class="hint">具体评分维度与权重以本周期引用的模板为准。自评与他评分别保存；最终成绩使用有效他评计算。</p></section></aside></div><div class="bottom"><section id="archive-departments" class="card"><h3><i>03</i> 部门表现分析</h3><p class="hint">按历史部门独立展示，不进行跨部门排名。</p><button v-for="d in departments" :key="d.id??'none'" class="item" @click="emit('department',d)"><span>{{d.name}}</span><span>{{d.count}} 人</span><b>›</b></button><p v-if="!departments.length" class="empty">暂无正式发布的部门结果</p></section><section id="archive-exceptions" class="card"><h3><i>04</i> 异常与问题回顾</h3><p v-if="exceptionError" class="empty">{{exceptionError}}</p><template v-else-if="exceptions"><div v-for="c in counts" :key="c.label" class="item"><span>{{c.label}}</span><b>{{c.count}}</b></div><RouterLink :to="{path:'/management/monthly/exceptions',query:{cycleId:detail.cycle.id}}">进入异常核验 →</RouterLink></template><p v-else class="empty">正在读取异常记录</p></section><section id="archive-ai" class="card"><h3><i>05</i> AI 成长总结</h3><p class="hint">组织及部门级 AI 成长报告尚未接入。</p></section></div></div></template>
<style scoped>
.report{color:#172d4d}.report-head h2{margin:0;font-size:23px}.report-head h2 small{font-size:12px;color:#2c6be9;background:#eaf1ff;border-radius:6px;padding:5px 8px}.report-head p,.hint{color:#75859d;font-size:12px;line-height:1.7}.summary{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px;margin:18px 0;padding:19px;background:#f7faff;border-radius:9px}.summary span{display:block;font-size:12px;color:#8190a3;margin-bottom:7px}.summary b{font-size:13px}.layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(210px,1fr);gap:14px}.layout main,.layout aside{display:grid;gap:14px;align-content:start}.card{border:1px solid #e6edf6;border-radius:10px;padding:20px;background:white;min-width:0}.card h3{font-size:16px;margin:0 0 10px}.card h3 i{font-size:22px;color:#3170f7;font-style:italic;margin-right:6px}.card h3 small{font-size:12px;color:#71839a;font-weight:normal;margin-left:10px}.charts{display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center}.distribution{display:flex;align-items:center;gap:12px}.pie{width:155px;height:155px;position:relative;flex:none}.chart{width:100%;height:100%}.pie-label{position:absolute;inset:0;display:flex;justify-content:center;align-items:center;flex-direction:column;pointer-events:none;font-size:12px}.legend{flex:1}.legend div{font-size:12px;display:flex;gap:8px;align-items:center;padding:6px 0}.legend em{width:9px;height:9px;border-radius:2px}.legend span{margin-left:auto}.dimensions strong{font-size:13px}.dimension{display:flex;align-items:center;gap:8px;margin:12px 0;font-size:12px}.dimension span{min-width:65px}.dimension progress{width:100%;height:7px;accent-color:#3370ff}.dimension b{min-width:42px}.note{background:#f3f7fd;border-radius:6px;padding:12px;color:#5d7392;font-size:12px;line-height:1.7}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:10px;text-align:left;border-bottom:1px solid #edf1f7}th{background:#f4f7fc;color:#6b7e98}details{margin:15px 0}summary{cursor:pointer;color:#315d9e;font-weight:600}.guide a{display:block;text-decoration:none;color:#365b91;background:#f6f9fe;margin:6px 0;padding:10px;border-radius:6px;font-size:13px}.bottom{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:14px}.item{display:flex;justify-content:space-between;align-items:center;width:100%;border:0;border-radius:6px;background:#f6f9fe;color:#27486e;padding:11px;margin:6px 0;font:inherit;font-size:12px;text-align:left}.item button,button.item{cursor:pointer}.item b{color:#2868ed}.empty{color:#8a99ab;text-align:center;padding:25px;font-size:13px}.card a{color:#2868ed;font-size:12px}@media(max-width:1050px){.summary{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}.layout aside{grid-template-columns:repeat(2,1fr)}.bottom{grid-template-columns:1fr 1fr}.charts{grid-template-columns:1fr}}@media(max-width:650px){.summary{grid-template-columns:repeat(2,1fr)}.layout aside,.bottom{grid-template-columns:1fr}.distribution{flex-wrap:wrap}.card{padding:15px}}
</style>
